/* global gtag, turnstile */
(function(){'use strict';var cfg=document.getElementById('dl-config');if(!cfg)return;var i18n={loading:cfg.dataset.i18nLoading,processing:cfg.dataset.i18nProcessing,pending:cfg.dataset.i18nPending,download:cfg.dataset.i18nDownload,downloadReady:cfg.dataset.i18nDownloadReady,tryAgain:cfg.dataset.i18nTryAgain,newDownload:cfg.dataset.i18nNewDownload,errorEmpty:cfg.dataset.i18nErrorEmpty,errorGeneric:cfg.dataset.i18nErrorGeneric,audio:cfg.dataset.i18nAudio,captchaLabel:cfg.dataset.i18nCaptchaLabel,captchaError:cfg.dataset.i18nCaptchaError};var siteKey=cfg.dataset.turnstileSitekey||'';var epDl=cfg.dataset.ep;var epSt=cfg.dataset.epS;var resultsEl=document.getElementById('dl-results');var form=document.querySelector('.hero-f');if(!resultsEl||!form)return;var state={selectedIdx:null,pollTimer:null,turnstileWidgetId:null};if(window.location.search&&window.location.search.indexOf('v=')!==-1){if(window.history&&window.history.replaceState){window.history.replaceState({},'',window.location.pathname);}}
function parsePlatform(url){try{var parts=new URL(url).hostname.split('.');return parts[parts.length-2].toUpperCase();}catch(e){return'OTHER';}}
function platformFromPath(){return window.location.pathname;}
function gaEvent(name){if(typeof gtag!=='function')return;var safe=name.toLowerCase().replace(/[^a-z0-9_]/g,'_').replace(/_+/g,'_').replace(/^_|_$/g,'').substring(0,40);gtag('event',safe);}
form.addEventListener('submit',function(e){e.preventDefault();var input=form.querySelector('input[name="url"]');var url=input?input.value.trim():'';if(!url){showError(i18n.errorEmpty);return;}var platform=parsePlatform(url);showLoading();fetch(form.action,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({url:url})}).then(function(r){return r.json().then(function(d){gaEvent('web_'+platform+'_'+r.status);if(!r.ok)throw new Error(d.error||i18n.errorGeneric);return d;});}).then(function(data){window.location.href=data.to;}).catch(function(err){showError(err.message||i18n.errorGeneric);});});
resultsEl.addEventListener('click',function(e){var fmtBtn=e.target.closest('.dl-fmt');if(fmtBtn){var fmtIdx=parseInt(fmtBtn.dataset.idx,10);state.selectedIdx=fmtIdx;var all=resultsEl.querySelectorAll('.dl-fmt');for(var i=0;i<all.length;i++)all[i].setAttribute('aria-pressed','false');fmtBtn.setAttribute('aria-pressed','true');showDownloadButton(fmtIdx,fmtBtn.dataset.label||fmtBtn.textContent.trim());return;}var startBtn=e.target.closest('.dl-start-btn');if(startBtn){if(state.selectedIdx===null||state.selectedIdx===undefined)return;if(siteKey){var card=resultsEl.querySelector('.dl-card');if(card){var s=card.querySelector('.dl-dl-section');if(s)s.remove();}showCaptcha(state.selectedIdx);}else{triggerDownload(state.selectedIdx,null);}return;}if(e.target.closest('.dl-reset')||e.target.closest('.dl-new-btn')){resetUI();}});
function triggerDownload(idx,captchaToken){var tokEl=document.getElementById('dl-tok');var nonEl=document.getElementById('dl-non');if(!tokEl||!nonEl||!tokEl.value||!nonEl.value){showError(i18n.errorGeneric);return;}var body={token:tokEl.value,nonce:nonEl.value,format_index:idx};if(captchaToken)body.cf_turnstile_response=captchaToken;var dlPlatform=platformFromPath();showProcessing();fetch(epDl,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}).then(function(r){return r.json().then(function(d){gaEvent('web_p_'+dlPlatform+'_dl_'+r.status);if(!r.ok)throw new Error(d.error||i18n.errorGeneric);return d;});}).then(function(resp){if(!resp.task_id){showError(i18n.errorGeneric);return;}pollStatus(resp.task_id,dlPlatform);}).catch(function(err){showError(err.message||i18n.errorGeneric);});}
function showCaptcha(idx){var card=resultsEl.querySelector('.dl-card');if(!card)return;removeCaptcha(card);var cap=document.createElement('div');cap.className='dl-captcha';cap.innerHTML='<div class="dl-captcha-label">'+escHtml(i18n.captchaLabel)+'</div>'+'<div class="dl-captcha-widget"><div id="dl-ts-w"></div></div>';card.appendChild(cap);if(typeof turnstile==='undefined'){showError(i18n.captchaError);return;}state.turnstileWidgetId=turnstile.render('#dl-ts-w',{sitekey:siteKey,retry:'auto',callback:function(t){removeCaptcha(card);triggerDownload(idx,t);},'error-callback':function(){showError(i18n.captchaError);},'expired-callback':function(){showCaptcha(idx);}});}
function removeCaptcha(card){if(state.turnstileWidgetId!==null&&typeof turnstile!=='undefined'){try{turnstile.remove(state.turnstileWidgetId);}catch(e){}state.turnstileWidgetId=null;}var el=card.querySelector('.dl-captcha');if(el)el.remove();}
function showLoading(){resultsEl.hidden=false;resultsEl.innerHTML='<div class="dl-card"><div class="dl-loading">'+'<div class="dl-spinner"></div>'+'<div class="dl-loading-text">'+escHtml(i18n.loading)+'</div>'+'</div></div>';}
function showDownloadButton(idx,label){var card=resultsEl.querySelector('.dl-card');if(!card)return;var old=card.querySelector('.dl-dl-section');if(old)old.remove();removeCaptcha(card);var section=document.createElement('div');section.className='dl-dl-section';section.innerHTML='<button class="dl-start-btn" data-idx="'+idx+'">'+'<svg viewBox="0 0 24 24" width="18" height="18" fill="currentColor" aria-hidden="true">'+'<path d="M21 15v4a2 2 0 01-2 2H5a2 2 0 01-2-2v-4M7 10l5 5 5-5M12 15V3"/>'+'</svg>'+escHtml(i18n.download)+' &nbsp;&middot;&nbsp; '+escHtml(label)+'</button>';card.appendChild(section);}
function showProcessing(){var card=resultsEl.querySelector('.dl-card');if(!card)return;['dl-formats','dl-dl-section','dl-captcha','dl-progress','dl-actions'].forEach(function(cls){var el=card.querySelector('.'+cls);if(el)el.remove();});var prog=document.createElement('div');prog.className='dl-progress';prog.innerHTML='<div class="dl-pbar" role="progressbar" aria-valuenow="0" aria-valuemin="0" aria-valuemax="100">'+'<div class="dl-pbar-fill"></div>'+'</div>'+'<div class="dl-pbar-text">'+escHtml(i18n.processing)+'</div>';card.appendChild(prog);}
function updateProgress(pct,text){var fill=resultsEl.querySelector('.dl-pbar-fill');var bar=resultsEl.querySelector('.dl-pbar');var txt=resultsEl.querySelector('.dl-pbar-text');if(fill)fill.style.width=pct+'%';if(bar)bar.setAttribute('aria-valuenow',pct);if(txt&&text)txt.textContent=text;}
function showComplete(url,platform){clearPoll();gaEvent('web_p_'+platform+'_success');var card=resultsEl.querySelector('.dl-card');if(!card)return;var prog=card.querySelector('.dl-progress');if(prog)prog.remove();var acts=document.createElement('div');acts.className='dl-actions';acts.innerHTML='<a class="dl-btn dl-btn-primary" href="'+escAttr(url)+'" target="_blank" rel="noopener">'+'<svg viewBox="0 0 24 24" width="16" height="16" fill="currentColor" aria-hidden="true">'+'<path d="M21 15v4a2 2 0 01-2 2H5a2 2 0 01-2-2v-4M7 10l5 5 5-5M12 15V3"/>'+'</svg>'+escHtml(i18n.download)+'</a>'+'<button class="dl-btn dl-btn-secondary dl-new-btn">'+escHtml(i18n.newDownload)+'</button>';card.appendChild(acts);}
function showError(msg){clearPoll();resultsEl.hidden=false;resultsEl.innerHTML='<div class="dl-card"><div class="dl-error">'+'<div class="dl-error-msg"></div>'+'<button class="dl-reset">'+escHtml(i18n.tryAgain)+'</button>'+'</div></div>';resultsEl.querySelector('.dl-error-msg').textContent=msg;}
function resetUI(){clearPoll();var card=resultsEl.querySelector('.dl-card');if(card)removeCaptcha(card);resultsEl.hidden=true;resultsEl.innerHTML='';state.selectedIdx=null;var input=form.querySelector('input[name="url"]');if(input){input.value='';input.focus();}}
function clearPoll(){if(state.pollTimer){clearInterval(state.pollTimer);state.pollTimer=null;}}
function pollStatus(taskId,platform){updateProgress(5,i18n.pending);state.pollTimer=setInterval(function(){fetch(epSt+taskId+'/').then(function(r){return r.json();}).then(function(data){if(data.state==='PROGRESS'){var pct=10;if(data.progress&&typeof data.progress==='object'){pct=data.progress.percent||data.progress.progress||50;}updateProgress(Math.min(pct,95),i18n.processing);}else if(data.state==='SUCCESS'){updateProgress(100,i18n.downloadReady);showComplete(data.presigned_url,platform);}else if(data.state==='FAILURE'){gaEvent('web_p_'+platform+'_fail');showError(data.status||i18n.errorGeneric);}}).catch(function(){showError(i18n.errorGeneric);});},2000);}
function escHtml(s){var d=document.createElement('div');d.textContent=s;return d.innerHTML;}
function escAttr(s){return s.replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
var preSelected=resultsEl.querySelector('.dl-fmt[aria-pressed="true"]');if(preSelected){state.selectedIdx=parseInt(preSelected.dataset.idx,10);showDownloadButton(state.selectedIdx,preSelected.dataset.label||preSelected.textContent.trim());}})();